46	/**
47	 * Validate upload size.
48	 *
49	 * Throws a FatalError if the size exceeds the maximum allowed upload size.
50	 *
51	 * @param sizeBytes the size of the object to upload in bytes
52	 */
53	export function validateUploadSize(key: string, sizeBytes: number): void {
54		if (sizeBytes > MAX_UPLOAD_SIZE_BYTES) {
55			throw new FatalError(
56				`Error: Wrangler only supports uploading files up to ${prettyBytes(
57					MAX_UPLOAD_SIZE_BYTES,
58					{ binary: true }
59				)} in size\n${key} is ${prettyBytes(sizeBytes, {
60					binary: true,
61				})} in size`,
62				1
63			);
64		}
65	}
