24	export async function confirm(
25		text: string,
26		{ defaultValue = true, fallbackValue = true }: ConfirmOptions = {}
27	): Promise<boolean> {
28		if (isNonInteractiveOrCI()) {
29			logger.log(`? ${text}`);
30			logger.log(
31				`🤖 ${chalk.dim(
32					"Using fallback value in non-interactive context:"
33				)} ${chalk.white.bold(fallbackValue ? "yes" : "no")}`
34			);
35			return fallbackValue;
36		}
37		const { value } = await prompts({
38			type: "confirm",
39			name: "value",
40			message: text,
41			initial: defaultValue,
42			onState: (state) => {
43				if (state.aborted) {
44					process.nextTick(() => {
45						process.exit(1);
46					});
47				}
48			},
49		});
50		return value;
51	}
