59	export async function prompt(
60		text: string,
61		options: PromptOptions = {}
62	): Promise<string> {
63		if (isNonInteractiveOrCI()) {
64			if (options?.defaultValue === undefined) {
65				throw new NoDefaultValueProvided();
66			}
67			logger.log(`? ${text}`);
68			logger.log(
69				`🤖 ${chalk.dim(
70					"Using default value in non-interactive context:"
71				)} ${chalk.white.bold(options.defaultValue)}`
72			);
73			return options.defaultValue;
74		}
75		const { value } = await prompts({
76			type: "text",
77			name: "value",
78			message: text,
79			initial: options?.defaultValue,
80			style: options?.isSecret ? "password" : "default",
81			validate: options.validate,
82			onState: (state) => {
83				if (state.aborted) {
84					process.nextTick(() => {
85						process.exit(1);
