144		complianceConfig: ComplianceConfig,
145		resource: string,
146		init: RequestInit = {},
147		queryParams?: URLSearchParams
148	): Promise<ResponseType> {
149		let cursor: string | undefined;
150		let results: ResponseType = [] as ResponseType;
151	
152		const page = parseInt(queryParams?.get("page") ?? "1", 10);
153		// Remove 'page' to then use cursor
154		queryParams?.delete("page");
155	
156		for (let currentPage = 1; currentPage <= page; currentPage++) {
157			const pageQueryParams = new URLSearchParams(queryParams);
158			if (cursor) {
159				pageQueryParams.set("cursor", cursor);
160			}
161	
162			const { response: json, status } = await fetchInternal<
163				FetchResult<ResponseType>
164			>(complianceConfig, resource, init, pageQueryParams);
165	
166			if (json.success) {
