import { confirm } from "../../dialogs";
import { logger } from "../../logger";

/**
 * HTTP header that asks the R2 API to reject a write when the target bucket has
 * a data catalog enabled. When present, the API responds with an HTTP 409 and
 * error code {@link R2_DATA_CATALOG_CONFLICT_CODE} instead of performing the
 * write, allowing us to prompt the user before proceeding.
 */
export const R2_DATA_CATALOG_CHECK_HEADER = "cf-r2-data-catalog-check";

/**
 * Error code returned (alongside HTTP 409) when a write is rejected because the
 * bucket has a data catalog enabled.
 */
export const R2_DATA_CATALOG_CONFLICT_CODE = 10081;

const DATA_CATALOG_CONFLICT_PROMPT =
	"Data catalog is enabled for this bucket. Proceeding may leave the data catalog in an invalid state. Continue?";

/**
 * Returns whether `error` represents an R2 data catalog conflict, i.e. an HTTP
 * 409 response carrying error code {@link R2_DATA_CATALOG_CONFLICT_CODE}.
 */
export function isDataCatalogConflict(error: unknown): boolean {
	return error instanceof APIError && error.code === R2_DATA_CATALOG_CONFLICT_CODE;
}

/**
 * Runs a write `operation` guarded by the R2 data catalog safety check.
 *
 * The `operation` callback is passed whether it should send the
 * {@link R2_DATA_CATALOG_CHECK_HEADER} header:
 * - When `force` is `true`, the operation runs once without the header.
 * - When `force` is `false`, the operation first runs with the header. If the
 *   API reports a data catalog conflict, the user is prompted; if they confirm,
 *   the operation is retried without the header, otherwise it is cancelled.
 *
 * @returns `true` if the operation ran to completion, `false` if the user
 *   declined the confirmation prompt.
 */
export async function runWithDataCatalogCheck(
	force: boolean,
	operation: (dataCatalogCheck: boolean) => Promise<void>
): Promise<boolean> {
	if (force) {
		await operation(false);
		return true;
	}

	try {
		await operation(true);
		return true;
	} catch (error) {
		if (!isDataCatalogConflict(error)) {
			throw error;
		}

		const confirmed = await confirm(DATA_CATALOG_CONFLICT_PROMPT);
		if (!confirmed) {
			logger.log("Operation cancelled.");
			return false;
		}

		await operation(false);
		return true;
	}
}
